#!/usr/bin/env python3
"""CPU audit of low-rank numeric result and its sequence-accounting undercount."""
import ast,hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];RUN=ROOT/'basis_aligned/bilinear_quotient/ops/run_numeric_shared_payload_low_rank_v1.py';RESULT=ROOT/'basis_aligned/polynomial_causal/NUMERIC_SHARED_PAYLOAD_LOW_RANK_V1_RESULT.json';OUT=ROOT/'basis_aligned/polynomial_causal/NUMERIC_SHARED_PAYLOAD_LOW_RANK_V1_AUDIT.json'
